csui.define('d2/overrides/csui/integration/folderbrowser/commands/go.to.node.history',[
  'require',
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'csui/integration/folderbrowser/commands/go.to.node.history'
], function (require, $, _, GoToNodeHistoryCommand) {
  'use strict';

  csui.require(['csui/utils/contexts/factories/next.node'], function (NextNodeModelFactory) {
    var proto = GoToNodeHistoryCommand.prototype/*,
      origEnabled = proto.enabled,
      origExecute = proto.execute*/;

    _.extend(proto, {
      enabled: function (status, options) {
        var context = status.context || options && options.context,
          isEnabled = (context.visitedNodeHistory && context.visitedNodeHistory.length > 1);
        return isEnabled;
      },

      execute: function (status, options) {
        var deferred = $.Deferred(),
          context = status.context || options && options.context,
          nextNode = context.getModel(NextNodeModelFactory);

        if ( context.visitedNodeHistory.length > 1) {
          context.visitedNodeHistory.pop();
          var nextNodeId =  context.visitedNodeHistory[ context.visitedNodeHistory.length - 1];
          if(nextNodeId === 'search'){
            //Remove Search entry from visited history
            context.visitedNodeHistory.pop();
            window.history.go(-1);
          } else {
            nextNode.set('id', nextNodeId);
          }
        }
        return deferred.resolve().promise();
      },
    });
  });
});
