csui.define('d2/widgets/document.overview/document.thumbnail.loader',[
  'nuc/lib/jquery',
  'nuc/lib/marionette',
  'nuc/utils/base',
  'd2/models/node.thumbnail.model'
], function ($, Marionette, base, ThumbnailModel) {
  'use strict';

  var ThumbnailLoader = Marionette.Object.extend({

    constructor: function ThumbnailLoader(/*options*/) {
      Marionette.Object.prototype.constructor.apply(this, arguments);
    },

    url: function() {
      return undefined;
    },

    loadUrl: function() {
      return this.load();
    },

    load: function () {
      return new ThumbnailModel(this.options.node).fetch({
        success: function (model) {
          var thumbnail_url = model.get('thumbnail_url');
          if (thumbnail_url) {
            this.triggerMethod('loadUrl', this, thumbnail_url);
          } else {
            this.triggerMethod('error', this);
          }
        }.bind(this),
        error: function (model, response, options/*, err*/) {
          this.handleFailure(options.xhr);
        }.bind(this)
      });
    },

    handleFailure: function (xhr) {
      this.url = null;
      var error = new base.Error(xhr);
      this.triggerMethod('error', this, error);
    }
  });

  return ThumbnailLoader;
});