csui.define('d2/overrides/csui/controls/table/cells/select/select.view',[
  'csui/controls/table/cells/select/select.view'
], function (SelectCellView) {
  'use strict';

  var prototype = SelectCellView.prototype,
    origRenderValue = prototype.renderValue;

  prototype.renderValue = function () {
    this.listenTo(this.model, 'change:' + 'selectable', function (model, changedValue) {
      this.checkboxView.setDisabled(!changedValue);
    });
    origRenderValue.call(this);
  };
});
