import { settings } from 'i18n';

const pluralRules = new Intl.PluralRules(settings.locale);

export function getPluralMessageForCardinal(messages, messagePrefix, number) {
  // get the plural form name: zero, one, two, few, many or other
  const pluralForm = pluralRules.select(number);
  // try the specific plural form: "message_zero", for example
  const message = messages[`${messagePrefix}_${pluralForm}`];
  // default to "other", if the language pack is not complete
  /* istanbul ignore next: Generally this will not fail as it is related to the count of references */
  return message ?? messages[`${messagePrefix}_other`];
}
