csui.define('d2/models/savedsearch/savedsearch.columns',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/backbone',
], function ($, _, Backbone) {
  'use strict';

  var SavedSearchColumnModel = Backbone.Model.extend({

    idAttribute: "key",

    defaults: {
      key: null,  // key from the resource definitions
      sequence: 0 // smaller number moves the column to the front
    }

  });

  var SavedSearchTableColumnCollection = Backbone.Collection.extend({

    model: SavedSearchColumnModel,
    comparator: "sequence",

    getColumnKeys: function () {
      return this.pluck('key');
    },

    deepClone: function () {
      return new SavedSearchTableColumnCollection(
        this.map(function (column) {
          return column.attributes;
        }));
    }
  });

  return SavedSearchTableColumnCollection;
});