csui.define('d2/dialogs/new.file/create/create.metadata.propertypage.view',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'nuc/lib/backbone',
  'nuc/lib/marionette',
  'd2/dialogs/new.file/profile.metadata.properties.view',
  'd2/controls/behaviors/wizard.tabable.region.behavior',
  'i18n!d2/dialogs/new.file/create/impl/nls/lang',
  'css!d2/dialogs/new.file/create/impl/create.metadata.propertypage'
], function (_, $, Backbone, Marionette, ItemMetadataPropertiesView, WizardTabableRegionBehavior, lang) {
  'use strict';

  var CreateMetadataPropertiesView = ItemMetadataPropertiesView.extend({


    className: function () {
      return ItemMetadataPropertiesView.prototype.className.call(this) + ' create-metadata-properties';
    },

    constructor: function CreateMetadataPropertiesView(options) {

      this.behaviors = _.extend({
        WizardTabableRegion: {
          behaviorClass: WizardTabableRegionBehavior
        }
      }, this.behaviors);
      options.mode = 'spy';

      options.parent = options.wizard;
      ItemMetadataPropertiesView.prototype.constructor.call(this, options);
      this.options.wizard = options.wizard;
      this.isLinkedDoc = options.isLinkedDoc;

      this.listenTo(this, 'metadata:form:validation', this.onValidateForm)
          .listenTo(this, 'metadata:form:field:change', this.validate)
          .listenTo(this, 'metadata:form:render:validation', this.onRenderValidation);

    },
    onValidateForm: function (isValid) {
      if (isValid) {
        this.nextButtonDisabled = false;
        this.options.wizard.refreshFooter();
      } else {
        this.nextButtonDisabled = true;
        this.options.wizard.refreshFooter();
      }
    },

    onRenderValidation: function (isValid) {
      this.onValidateForm(isValid);
    },

    validate: function () {
      var deferred = $.Deferred();
      this.validateAllForms(true).done(function (isValid) {
        if (isValid === false) {
          this.onValidateForm(isValid);
        }
        deferred.resolve(isValid);
      }.bind(this));
      return deferred;
    },

    getTitle: function () {
      return this.isLinkedDoc ? lang.propertiesLinkedDocTitle : lang.propertiesTitle;
    },

    onBeforeShow: function () {
      this.refreshForms();
      var tokenId = this.options.node._tokenId;
      if (tokenId) {
        //Listen on Change event now!!!
        this.options.node._changedFormValuesMap = {
          "properties": {},
          "signoffInputs": {}
        };
      }
    }

  });

  return CreateMetadataPropertiesView;
});