csui.define('d2/server.adaptors/models/objecttypes.mixin',[
  'nuc/lib/underscore',
  'nuc/lib/jquery'
], function(_, $){
  'use strict';

  return {
    mixin: function(prototype) {
      _.extend(prototype, {
        makeServerAdaptor: function() {
          return this;
        },

        sync: function(method, model, options) {
          var succssFn = options.success;
          if(_.isFunction(succssFn)) {
            setTimeout(function(){
              succssFn({});
            }, 0);
          }
          return $.Deferred().resolve().promise();
        }
      });
    }
  };
});