csui.define('d2/overrides/csui/controls/thumbnail/content/text/text.view',[
    'csui/controls/table/cells/date/date.view'
], function (DateCellView) {
    csui.require([
        'csui/controls/thumbnail/content/text/text.view'
    ], function (ThumbnailTextView) {
        'use strict';

        var prototype = ThumbnailTextView.prototype,
            ThumbnailGetValueText = prototype.getValueText,
            DateCellFormatFunction = DateCellView.prototype.formatFunction;

        prototype.getValueText = function () {
            var valueText = ThumbnailGetValueText.apply(this, arguments),
                column = this.options.column,
                columns = this.options.columns,
                columnAttributes = columns && columns.findWhere({column_key: column.key}) ? columns.findWhere({column_key: column.key}).attributes : {};

            if (columnAttributes?.type === -7) {
                var formatOptions = {includeTime: columnAttributes.include_time !== false};

                var formatFunction = DateCellFormatFunction;

                var formatter = function (singleValue) {
                    return formatFunction(singleValue, formatOptions);
                }

                valueText = this.getSingleOrMultipleValueText(valueText, formatter);
            }

            return valueText;
        }
    });
});