csui.define('d2/overrides/csui/widgets/metadata/impl/header/dropdown.menu/dropdown.menu.view',[
  'require',
  'nuc/lib/underscore',
  'nuc/lib/marionette',
  'csui/widgets/metadata/metadata.view'
], function (require, _, Marionette) {
  'use strict';

  //TODO: Check and remove this whole thing when SVF-132 is fixed

  csui.require([
    'csui/widgets/metadata/impl/header/dropdown.menu/dropdown.menu.view'
  ], function (CSMetadataDropdownMenuView) {

    var origOnRender = CSMetadataDropdownMenuView.prototype.onRender,
        origRenderChildren = CSMetadataDropdownMenuView.prototype._renderChildren;

    CSMetadataDropdownMenuView.prototype.onRender = function () {
      if (this.options.toolItems.collection.length && !this.collection.length && this.model.commands) {
        // VE-OCTCR77IV4703814
        // Since the if (!this.model.get('csuiLazyActionsRetrieved')) block is not needed now, we'll remove this block
        if (this.model.get('d2ObjectDataFetched') === true && this.model.actions && this.model.actions.length > 0) {
          this._updateMenuItems();
          return;
        }
      }

      //Adding this listener since CSUI on fetching lazy actions just updates the newly fetched collection based on their signatures and if they are already present or not
      //For our usecase, we can have multiple actions with the same signature, so refiltering the entire toolitem collection is better option
      this.listenTo(this.model.actions, 'update', updateToolbarCollection.bind(this));

      return origOnRender.apply(this, arguments);
    }

    CSMetadataDropdownMenuView.prototype._renderChildren = function () {
      let childViewContainer = Marionette.getOption(this, 'childViewContainer');
      if (childViewContainer && this.$el?.find(childViewContainer).length === 0) {
        return;
      }
      return origRenderChildren.apply(this, arguments);
    }

    function updateToolbarCollection() {
      //This will be triggered before the control reaches back to dropdown.menu.view after fetching of actions is finished
      if (this.fetchingNonPromotedActions === false) {
        var me = this;
        setTimeout(function () {
          me.collection.refilter && me.collection.refilter();
        }, 301); //Waiting 301ms so that the loader animation is finished
      } else {
        setTimeout(updateToolbarCollection.bind(this));
      }
    }
  });
});