csui.define('d2/commands/workflow/show.workflow.history',[
  'nuc/lib/underscore',
  'nuc/lib/jquery',
  'csui/models/command',
  'csui/utils/commandhelper',
  'csui/utils/contexts/factories/application.scope.factory',
  'd2/utils/constants',
  'dctmw/utils/user.preference.storage',
  'd2/utils/contexts/factories/widget.view.state.factory',
  'i18n!d2/commands/nls/localized.strings'
], function (_, $, CommandModel, CommandHelper, ApplicationScopeModelFactory, constants, userPreference, WidgetViewStateModelFactory, lang) {
  'use strict';

  return CommandModel.extend({
    defaults: {
      signature: 'D2-ShowWorkflowHistory',
      command_key: 'D2-ShowWorkflowHistory',
      name: lang.CommandNameShowWorkflowHistory,
      scope: 'single'
    },
    execute: function (status, options) {
      var context = status.context || options.context,
        appScope = context.getModel(ApplicationScopeModelFactory),
        viewStateModel = context.viewStateModel,
        node = CommandHelper.getJustOneNode(status),
        qParamData = JSON.stringify({
          'document-id': node.get('id'),
          'wf-states': [constants.WorkflowState.SCHEDULED, constants.WorkflowState.PAUSED, constants.WorkflowState.RUNNING]
        }),
        widgetViewStateModel = context.getObject(WidgetViewStateModelFactory);

      widgetViewStateModel && widgetViewStateModel.set('qform-param', qParamData);
      userPreference.saveLocalStorePreference(userPreference.StorageTypes.SEARCH_PANEL_VISIBILITY, constants.WidgetId.WORKFLOWS, true);
      viewStateModel.set('enabled', true);
      appScope.set('id', 'allworkflows');
      /*
       Root perspective plugin implementations are depending on view state model for building URL.
       If URL is not cleared from View state model, then same filter is applied in workflow list perspective also.
       For avoid this behavior, clearing filter from view state model and
       clearing filter from collection for avoiding fecth call from browsable mixin on filter value change.
      */
      status.collection && status.collection.clearFilter(false);
      var state = viewStateModel.get(viewStateModel.CONSTANTS.STATE) || {};
      state = _.clone(state);
      state['filter'] = '';
      state['order_by'] = '';
      state['page'] = '';
      state['qform-param'] = '';
      viewStateModel.set(viewStateModel.CONSTANTS.STATE, state);
      return $.Deferred().resolve().promise();
    }
  });
});