import TabableRegionBehavior from   'csui/behaviors/keyboard.navigation/tabable.region.behavior'
const origSetInitialTabIndex = TabableRegionBehavior.prototype.setInitialTabIndex;

TabableRegionBehavior.prototype.setInitialTabIndex = function(){
    // WizardTabableRegionBehavior was built to use inplace of TabableRegionBehavior when loaded in StepperWizardView, but current CSUI tab.panel.view.v2 
    // does not allow us to replace/override the behavior for metadata properties view. By default in tab.panel.view.v2, regionBehavior is provided with a new obj,
    // and the same is consumed as TabableRegionBehavior in smart tab.panel.view. So we will not be able to replace TabableRegionBehavior with WizardTabableRegionBehavior for now. 
    // When we have two TabableRegionBehavior, both will add focus event listener on the view, and to avoid recursive focus event capture, ignoreFocusEvents  flag is used. This will be set on the tabableRegionBehavior property on the view instance.
    // Since both the behaviors will be assigned on the same property, only one reference will be having the flag, and other behavior instance will try to trigger the event and unset the flag. Thus it will endup into a recursive infinite loop of events.
    // To avoid this, for now we are removing the existing events so only one behavior will be listening for the focus event. 
    // Once we get an option to pass the WizardTabableRegion via options as regionBehavior [LPAD-132631], we can remove this override and pass the WizardTabableBehavior via options in the extended metadata view class.
    
    if (!this.currentlyFocusedElement && this.view.isTabable()) {
        let currentlyFocusedElement = this.getCurrentlyFocusedElementFromView();
        currentlyFocusedElement?.off('focus.' + this.view.cid);
    }

    return origSetInitialTabIndex.apply(this, arguments);
}