csui.define('d2/controls/group.panel/impl/group.content.header.view',[
  'nuc/lib/marionette',
  'hbs!d2/controls/group.panel/impl/group.content.header',
  'i18n!d2/controls/group.panel/impl/nls/lang',
  'css!d2/controls/group.panel/impl/group.content.header'
], function (Marionette, template, lang) {
  'use strict';

  return Marionette.ItemView.extend({
    className: 'd2-group-content-header-view',

    template: template,

    templateHelpers: function () {
      return {
        name: this.options.name,
        subtitle: this.options.subtitle,
        indicateRequired: this.options.indicateRequired,
        initialExpand: this.options.initialExpand,
        expandTitle: lang.expandTitle,
        collapseTitle: lang.collapseTitle
      }
    },

    ui: {
      expandCollapse: '.d2-group-expandCollapse'
    },

    events: {
      'click @ui.expandCollapse': 'onClickExpandCollapse',
      'keyup @ui.expandCollapse': 'onKeyUpExpandCollapse'
    },

    constructor: function GroupContentHeaderView(/*options*/) {
      Marionette.ItemView.prototype.constructor.apply(this, arguments);
    },

    onKeyUpExpandCollapse: function (event) {
      switch (event.which) {
        case 13: // Enter
        case 32: // Space
          this.onClickExpandCollapse(event);
          break;
      }
    },

    onClickExpandCollapse: function (event) {
      event.stopPropagation();
      event.preventDefault();

      this.ui.expandCollapse.toggleClass(['expand', 'collapse']);

      this.ui.expandCollapse.attr('title', this.ui.expandCollapse.hasClass('collapse') ? lang.collapseTitle : lang.expandTitle);
      var isExpanded = this.ui.expandCollapse.hasClass('collapse');
      this.trigger('d2:group:expand:collapse', isExpanded);
      if(isExpanded){
        this.adjustScrollOnExpand();
      }
    },

    adjustScrollOnExpand:function(){
      if(this.options.groupContentView && this.options.groupContentView.groupPanelView){
        var me = this,
          groupContentView = me.options.groupContentView,
          groupPanelView = groupContentView.groupPanelView;
        setTimeout(function(){
          var scrollHeight = me.options.groupContentView.groupPanelView.el.scrollHeight,
            groupContentHeight = groupContentView.$el.outerHeight(),
            groupPanelHeight = groupPanelView.$el.outerHeight(),
            $focusableEl = groupContentView.contentView.$el.find('[tabindex]:visible:not([disabled])').first(),
            focusableElementTop = $focusableEl.offset().top - groupPanelView.$el.offset().top,
            scrollTopPosition = scrollHeight - groupContentHeight;
          if (focusableElementTop > groupPanelHeight) {
            me.options.groupContentView.groupPanelView.$el.scrollTop(scrollTopPosition);
          }
        },10);
      }
    }
  });
});